      const en = box.querySelector("#l-enroll"); if (en) en.addEventListener("click", () => { box.querySelector("#l-sub").innerHTML = `<div class="form" style="margin-top:12px"><h3>Записване</h3><div class="row"><label>Група<select id="e-group">${groups.map(g => `<option value="${g.id}">${g.name}</option>`).join("")}</select></label><label>Пакет<select id="e-pack">${DB.packages.map(p => `<option value="${p.id}">${p.name} · ${p.price} €</option>`).join("")}</select></label><label>Имейл на родителя<input id="e-mail" placeholder="за седмичния отчет"></label></div><button class="btn small good" id="e-save">Запиши и изпрати добре дошли</button></div>`; box.querySelector("#e-save").addEventListener("click", () => { const g = group(box.querySelector("#e-group").value), p = DB.packages.find(x => x.id === box.querySelector("#e-pack").value); const fid = "f" + Date.now(), cid = "k" + Date.now(); DB.families.push({ id: fid, centerId: l.centerId, contactName: l.contactName, phone: l.phone, email: box.querySelector("#e-mail").value || "", emailConsent: true, source: l.source }); const b = new Date(); b.setFullYear(b.getFullYear() - l.age); const nc = { id: cid, familyId: fid, centerId: l.centerId, firstName: l.childName, lastName: l.contactName.split(" ").slice(-1)[0] || "", birthDate: b.toISOString(), status: "active", createdAt: new Date().toISOString(), groupId: g.id, streakDays: 0 }; DB.children.push(nc); ensureAccess(nc, "записване"); DB.enrollments.push({ id: "e" + Date.now(), childId: cid, groupId: g.id, programId: g.programId, packageId: p.id, startDate: new Date().toISOString(), status: "active", pricePerLesson: p.price / p.lessons, discount: 0, lessonsLeft: p.lessons, balance: p.price }); DB.payments.unshift({ id: "pay" + Date.now(), childId: cid, amount: p.price, method: "в брой", kind: "плащане", at: new Date().toISOString(), userId: me().id }); l.status = "enrolled"; l.statusAt = new Date().toISOString(); l.enrolledAt = new Date().toISOString(); l.childId = cid; logEvent("child.enrolled", cid, `${l.childName} е записан в ${g.name}, пакет ${p.name}`); logEvent("payment.added", cid, `Плащане ${p.price} € за ${l.childName}`); logEvent("email.sent", cid, `Имейл „Добре дошли“ до ${l.contactName} с линк към страницата на детето`); save(); $("#modal").hidden = true; location.hash = "#child/" + cid; toast("Записан"); }); });
      const lo = box.querySelector("#l-lost"); if (lo) lo.addEventListener("click", () => { box.querySelector("#l-sub").innerHTML = `<div class="form" style="margin-top:12px"><label>Причина за отказа<select id="lost-r"><option>цена</option><option>далеч от центъра</option><option>неудобно време</option><option>избра друг център</option><option>детето не иска</option><option>без контакт</option><option>друго</option></select></label><button class="btn small bad" id="lost-save">Запиши отказ</button></div>`; box.querySelector("#lost-save").addEventListener("click", () => { l.status = "lost"; l.statusAt = new Date().toISOString(); l.lostAt = new Date().toISOString(); l.lostReason = box.querySelector("#lost-r").value; logEvent("lead.lost", l.id, `${l.childName}: отказ (${l.lostReason})`); save(); $("#modal").hidden = true; render(); }); });
