    return `<div class="head"><div><h1>Плащания</h1><p>Всяко проведено занятие отписва едно платено от присъствалите деца. Дете влиза в „За плащане“ при остатък от едно занятие; при нула достъпът до игрите спира до следващото плащане.</p></div></div>
    <div class="cards"><div class="kpi"><div class="l">Нетно този месец</div><div class="v">${month} €</div></div><div class="kpi ${due.length ? "warn" : "good"}"><div class="l">За плащане</div><div class="v">${due.length}</div><div class="s">${blocked ? `${blocked} със спрян достъп` : "никой със спрян достъп"}</div></div></div>
    <div class="panel"><h2>За плащане</h2><p class="muted" style="margin:0 0 8px">Родителят получава автоматичен имейл при 1 оставащо занятие и при 0. Обаждането при 0 е задача в „Днес“. След записано плащане детето изчезва оттук.</p><div class="tbl"><table><tr><th>Дете</th><th>Група</th><th>Остават</th><th>Последно плащане</th><th>Напомняне</th><th></th></tr>${due.map(d => `<tr><td><a href="#child/${d.c.id}"><b>${fullName(d.c)}</b></a><br><span class="muted">${family(d.c.familyId).contactName}, ${family(d.c.familyId).phone}</span></td><td>${group(d.c.groupId).name || "—"}</td><td>${d.e.lessonsLeft === 0 ? '<span class="pill b">0 · достъпът е спрян</span>' : '<span class="pill w">1 занятие</span>'}</td><td>${d.lastP ? `${fmtD(d.lastP.at)} · ${d.lastP.amount} €` : "—"}</td><td class="muted">${d.rem ? "имейл " + fmtD(d.rem.at) : "—"}</td><td><button class="btn small" data-pay="${d.c.id}">Приеми плащане</button></td></tr>`).join("") || `<tr><td colspan="6" class="muted">Всички деца са с платени занятия.</td></tr>`}</table></div></div>
    <div class="panel"><h2>Получени плащания</h2><div class="tbl"><table><tr><th>Дата</th><th>Дете</th><th>Сума</th><th>Занятия</th><th>Метод</th><th>Основание</th><th>Приел</th></tr>${ps.slice(0, 40).map(p => { const c = child(p.childId); return `<tr class="click" data-go="#child/${c.id}"><td>${fmtDT(p.at)}</td><td><b>${fullName(c)}</b></td><td class="num ${p.amount < 0 ? "warn" : ""}">${p.amount ? (p.amount < 0 ? "−" + Math.abs(p.amount) : p.amount) + " €" : "—"}</td><td class="num ${p.lessons < 0 ? "warn" : ""}">${p.lessons != null ? (p.lessons > 0 ? "+" : p.lessons < 0 ? "−" : "") + Math.abs(p.lessons) : "—"}</td><td>${p.method}</td><td class="muted">${p.kind === "връщане" || p.kind === "корекция" ? `<span class="pill w">${p.kind}</span> ` : ""}${p.note || ""}${p.credit ? ` <span class="muted">· кредит ${p.credit} €</span>` : ""}</td><td class="muted">${user(p.userId).name}</td></tr>`; }).join("")}</table></div></div>`;
