  function kpis(cid) {
    const leads = DB.leads.filter(l => !cid || l.centerId === cid), kids = DB.children.filter(c => !cid || c.centerId === cid), active = kids.filter(c => c.status === "active");
    const trials = leads.filter(l => l.trial), visited = trials.filter(l => l.trial.status === "visited" || l.status === "enrolled"), enrolled = leads.filter(l => l.status === "enrolled");
    const held = DB.lessons.filter(l => l.status === "held" && (!cid || l.centerId === cid)); const att = DB.attendance.filter(a => held.some(l => l.id === a.lessonId));
    const hwDone = active.filter(c => hwPct(hwOf(c.id)) >= 100).length; const hwAvg = active.length ? Math.round(active.reduce((a, c) => a + hwPct(hwOf(c.id)), 0) / active.length) : 0;
    const rev = DB.payments.filter(p => { const c = child(p.childId); return c && (!cid || c.centerId === cid) && new Date(p.at).getMonth() === new Date().getMonth(); }).reduce((a, p) => a + p.amount, 0);
    const lost = leads.filter(l => l.status === "lost").length + kids.filter(c => c.status === "finished").length;
    return { leads: leads.length, leadToTrial: pct(trials.length, leads.length), show: pct(visited.length, trials.length), trialToEnroll: pct(enrolled.length, visited.length || trials.length), active: active.length, attendance: pct(att.filter(a => a.present).length, att.length), hwAvg, hwDone: pct(hwDone, active.length), streak: active.length ? Math.round(active.reduce((a, c) => a + c.streakDays, 0) / active.length) : 0, revenue: rev, lost, teachers: DB.users.filter(u => u.role === "teacher" && (!cid || u.centerId === cid)).length };
  }
