    const byTeacher = DB.users.filter(u => u.role === "teacher" && (role === "hq" || u.centerId === centerId())).map(u => { const gs = DB.groups.filter(g => g.teacherId === u.id && g.status === "active"); const kids = DB.children.filter(c => c.status === "active" && gs.some(g => g.id === c.groupId)); const assigned = kids.filter(c => { const h = hwOf(c.id), last = DB.lessons.filter(l => l.groupId === c.groupId && l.status === "held").sort((a, b) => a.at < b.at ? 1 : -1)[0]; return h && last && h.assignedAt >= last.at; }).length; const stale = kids.filter(c => { const s = lastSessionAt(c.id); return !s || Date.now() - new Date(s) > 7 * day; }).length; const done = kids.length ? Math.round(kids.reduce((a, c) => a + hwPct(hwOf(c.id)), 0) / kids.length) : 0; return { u, groups: gs.length, kids: kids.length, assigned: pct(assigned, kids.length), done, stale }; });
