    <div class="cards">${KPI_DEF.map(([key, label, unit, target]) => `<div class="kpi ${target == null ? "" : k[key] >= target ? "good" : "warn"}"><div class="l">${label}</div><div class="v">${k[key]}${unit}</div>${target != null ? `<div class="s">ориентир ${target}${unit}</div>` : ""}</div>`).join("")}</div>
