    <div class="panel"><h2>Партньори и роялти</h2><p class="muted">Роялти се начислява автоматично на 1-во число от записаните деца и проведените занятия за миналия месец, независимо от плащанията. Срок: 10-то число, после е просрочено.</p><table><tr><th>Партньор</th><th>Центрове</th><th>Активни деца</th><th>Ставка</th><th>${ymLabel(ym(new Date()))} · натрупва се</th><th>Открити задължения</th><th>Статус</th></tr>${(DB.partners || []).map(pt => { const rs = rows.filter(r => pt.centers.includes(r.c.id)); const cur = royaltyCalc(pt, ym(new Date())); const open = (DB.royalties || []).filter(r => r.partnerId === pt.id && r.status !== "paid"); const worst = open.map(royaltyState).sort((a, b) => b[2] - a[2])[0]; return `<tr class="click" data-go="#royalty"><td><b>${pt.name}</b><br><span class="muted">${pt.contact} · ${pt.territory}</span></td><td>${rs.map(r => r.c.name).join(", ")}</td><td class="num">${rs.reduce((a, r) => a + r.active, 0)}</td><td class="num">${pt.royaltyRate * 100} %</td><td class="num">${eur(cur.amount)}</td><td class="num">${eur(open.reduce((s, r) => s + r.amount, 0))}</td><td>${worst ? `<span class="pill ${worst[1]}">${worst[0]}</span>` : '<span class="pill g">няма</span>'}</td></tr>`; }).join("")}</table></div>
